import http from "node:http";
import fs from "node:fs/promises";
import path from "node:path";
import crypto from "node:crypto";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const DATA_FILE = path.join(__dirname, "books.json");
const PORT = Number(process.env.PORT) || 3000;
const MAX_BODY = 1_000_000;

// ---------- storage ----------
async function readBooks() {
  try {
    const raw = await fs.readFile(DATA_FILE, "utf8");
    const data = JSON.parse(raw);
    return Array.isArray(data?.books) ? data.books : [];
  } catch (err) {
    if (err.code === "ENOENT") return [];
    console.error("books.json could not be read, starting fresh:", err.message);
    return [];
  }
}

async function writeBooks(books) {
  const tmp = DATA_FILE + ".tmp";
  await fs.writeFile(tmp, JSON.stringify({ books }, null, 2), "utf8");
  await fs.rename(tmp, DATA_FILE); // atomic on same filesystem
}

const findBook = (books, id) => books.find((b) => b.id === id);

// ---------- helpers ----------
function escapeHtml(s) {
  return String(s ?? "").replace(/[&<>"']/g, (c) => ({
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    '"': "&quot;",
    "'": "&#39;",
  }[c]));
}

function escapeAttr(s) {
  return escapeHtml(s).replace(/`/g, "&#96;");
}

// multi-line text -> safe paragraphs
function notesToHtml(notes) {
  return escapeHtml(notes)
    .split(/\n{2,}/)
    .map((p) => `<p>${p.replace(/\n/g, "<br>")}</p>`)
    .join("");
}

function parseForm(req) {
  return new Promise((resolve, reject) => {
    let data = "";
    req.on("data", (chunk) => {
      data += chunk;
      if (data.length > MAX_BODY) {
        reject(new Error("request body too large"));
        req.destroy();
      }
    });
    req.on("end", () => {
      const params = {};
      for (const pair of data.split("&")) {
        const idx = pair.indexOf("=");
        if (idx === -1) continue;
        const key = pair.slice(0, idx);
        const val = pair.slice(idx + 1);
        if (!key) continue;
        params[decodeURIComponent(key.replace(/\+/g, " "))] =
          decodeURIComponent(val.replace(/\+/g, " "));
      }
      resolve(params);
    });
    req.on("error", reject);
  });
}

function redirect(res, location) {
  res.writeHead(303, { Location: location });
  res.end();
}

function sendHtml(res, status, html) {
  res.writeHead(status, { "Content-Type": "text/html; charset=utf-8" });
  res.end(html);
}

function fullUrl(req, pathname) {
  const proto = req.headers["x-forwarded-proto"] || "http";
  const host = req.headers.host || `localhost:${PORT}`;
  return `${proto}://${host}${pathname}`;
}

function formatDate(iso) {
  if (!iso) return "";
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return "";
  return d.toLocaleDateString(undefined, {
    year: "numeric",
    month: "short",
    day: "numeric",
  });
}

// ---------- views ----------
const CSS = `
:root { --fg:#1a1a1a; --muted:#6b6b6b; --line:#e3e3e3; --accent:#3b6ea5; --bg:#fafafa; }
* { box-sizing: border-box; }
body { margin:0; font:16px/1.55 -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
  color:var(--fg); background:var(--bg); }
header { border-bottom:1px solid var(--line); background:#fff; }
header .wrap { max-width:720px; margin:0 auto; padding:14px 20px; display:flex; gap:16px; align-items:center; }
.brand { font-weight:700; font-size:18px; text-decoration:none; color:var(--fg); }
nav a { color:var(--accent); text-decoration:none; font-size:14px; }
main { max-width:720px; margin:0 auto; padding:28px 20px 60px; }
h1 { font-size:26px; margin:0 0 6px; }
h2 { font-size:18px; margin:28px 0 10px; color:var(--muted); text-transform:uppercase; letter-spacing:.04em; }
a { color:var(--accent); }
.muted { color:var(--muted); }
ul.books { list-style:none; padding:0; margin:0; }
ul.books li { padding:14px 16px; background:#fff; border:1px solid var(--line); border-radius:8px; margin-bottom:10px; }
ul.books li a { text-decoration:none; color:var(--fg); font-weight:600; font-size:17px; }
ul.books li a:hover { color:var(--accent); }
ul.books li .author { color:var(--muted); font-size:14px; margin-top:2px; }
ul.books li .meta { color:var(--muted); font-size:12px; margin-top:6px; }
.empty { color:var(--muted); padding:18px; border:1px dashed var(--line); border-radius:8px; text-align:center; }
form { max-width:520px; }
label { display:block; font-weight:600; margin:18px 0 6px; font-size:14px; }
input[type=text], textarea { width:100%; padding:10px 12px; border:1px solid var(--line); border-radius:6px;
  font:inherit; background:#fff; }
textarea { min-height:120px; resize:vertical; }
input:focus, textarea:focus { outline:2px solid var(--accent); border-color:var(--accent); }
.btn { display:inline-block; padding:9px 16px; border:1px solid var(--accent); background:var(--accent);
  color:#fff; border-radius:6px; font:inherit; cursor:pointer; text-decoration:none; }
.btn:hover { opacity:.9; }
.btn.secondary { background:#fff; color:var(--accent); }
.btn.danger { border-color:#b04a4a; background:#fff; color:#b04a4a; }
.btn.sm { padding:5px 10px; font-size:13px; }
.actions { margin-top:22px; display:flex; gap:10px; flex-wrap:wrap; }
.field-help { color:var(--muted); font-size:13px; margin-top:4px; }
.share { margin-top:24px; background:#fff; border:1px solid var(--line); border-radius:8px; padding:14px 16px; }
.share code { background:var(--bg); padding:2px 6px; border-radius:4px; font-size:13px; word-break:break-all; }
.book-detail h1 { margin-bottom:2px; }
.book-detail .author { color:var(--muted); font-size:17px; margin-bottom:4px; }
.notes { margin-top:24px; }
.notes p { margin:0 0 12px; }
.back { margin-bottom:20px; display:inline-block; font-size:14px; }
`;

function page(title, body, req) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escapeHtml(title)} &middot; Booklog</title>
<style>${CSS}</style>
</head>
<body>
<header>
  <div class="wrap">
    <a href="/" class="brand">Booklog</a>
    <nav><a href="/books/new">+ Add a book</a></nav>
  </div>
</header>
<main>
${body}
</main>
</body>
</html>`;
}

function homeView(books, req) {
  const reading = books.filter((b) => b.status === "reading");
  const finished = books
    .filter((b) => b.status === "finished")
    .sort((a, b) => (b.finishedAt || "").localeCompare(a.finishedAt || ""));

  const renderItem = (b) => `
    <li>
      <a href="/books/${encodeURIComponent(b.id)}">${escapeHtml(b.title)}</a>
      <div class="author">${escapeHtml(b.author || "Unknown author")}</div>
      <div class="meta">Added ${escapeHtml(formatDate(b.addedAt))}${
        b.finishedAt ? ` &middot; Finished ${escapeHtml(formatDate(b.finishedAt))}` : ""
      }</div>
    </li>`;

  const readingHtml = reading.length
    ? `<ul class="books">${reading.map(renderItem).join("")}</ul>`
    : `<div class="empty">Nothing in progress. <a href="/books/new">Add a book</a> to get started.</div>`;

  const finishedHtml = finished.length
    ? `<ul class="books">${finished.map(renderItem).join("")}</ul>`
    : `<div class="empty">No finished books yet.</div>`;

  return page(
    "Your books",
    `<h1>Your books</h1>
     <p class="muted">${books.length} total &middot; ${reading.length} reading &middot; ${finished.length} finished</p>
     <h2>Currently reading</h2>
     ${readingHtml}
     <h2>Finished</h2>
     ${finishedHtml}`,
    req
  );
}

function newBookView(req, values = {}, error = "") {
  const errHtml = error ? `<p style="color:#b04a4a;margin:0 0 12px">${escapeHtml(error)}</p>` : "";
  return page(
    "Add a book",
    `<a href="/" class="back">&larr; Back</a>
     <h1>Add a book</h1>
     ${errHtml}
     <form method="post" action="/books">
       <label for="title">Title</label>
       <input type="text" id="title" name="title" value="${escapeAttr(values.title || "")}" required autofocus>
       <label for="author">Author</label>
       <input type="text" id="author" name="author" value="${escapeAttr(values.author || "")}">
       <label for="notes">Notes</label>
       <textarea id="notes" name="notes" placeholder="What's it about? Thoughts so far...">${escapeHtml(values.notes || "")}</textarea>
       <div class="actions">
         <button type="submit" class="btn">Add book</button>
         <a href="/" class="btn secondary">Cancel</a>
       </div>
     </form>`,
    req
  );
}

function bookView(book, req) {
  const url = fullUrl(req, `/books/${encodeURIComponent(book.id)}`);
  const finishBtn = book.status === "reading"
    ? `<form method="post" action="/books/${encodeURIComponent(book.id)}/finish">
         <button type="submit" class="btn">Mark as finished</button>
       </form>`
    : `<span class="btn secondary">Finished ${escapeHtml(formatDate(book.finishedAt))}</span>`;

  const notesHtml = book.notes?.trim()
    ? notesToHtml(book.notes)
    : `<p class="muted">No notes yet.</p>`;

  return page(
    book.title,
    `<a href="/" class="back">&larr; Back to all books</a>
     <div class="book-detail">
       <h1>${escapeHtml(book.title)}</h1>
       <div class="author">${escapeHtml(book.author || "Unknown author")}</div>
       <div class="meta muted">Added ${escapeHtml(formatDate(book.addedAt))}</div>
     </div>
     <div class="actions">
       ${finishBtn}
       <a href="/books/${encodeURIComponent(book.id)}/edit" class="btn secondary">Edit notes</a>
       <form method="post" action="/books/${encodeURIComponent(book.id)}/delete"
             onsubmit="return confirm('Delete this book? This cannot be undone.');">
         <button type="submit" class="btn danger">Delete</button>
       </form>
     </div>
     <div class="notes">
       <h2>Notes</h2>
       ${notesHtml}
     </div>
     <div class="share">
       <strong>Shareable link</strong>
       <p class="muted" style="margin:6px 0">Anyone with this link can view this book:</p>
       <code>${escapeHtml(url)}</code>
     </div>`,
    req
  );
}

function editBookView(book, req, error = "") {
  const errHtml = error ? `<p style="color:#b04a4a;margin:0 0 12px">${escapeHtml(error)}</p>` : "";
  return page(
    "Edit book",
    `<a href="/books/${encodeURIComponent(book.id)}" class="back">&larr; Back</a>
     <h1>Edit book</h1>
     ${errHtml}
     <form method="post" action="/books/${encodeURIComponent(book.id)}/edit">
       <label for="title">Title</label>
       <input type="text" id="title" name="title" value="${escapeAttr(book.title)}" required>
       <label for="author">Author</label>
       <input type="text" id="author" name="author" value="${escapeAttr(book.author || "")}">
       <label for="notes">Notes</label>
       <textarea id="notes" name="notes">${escapeHtml(book.notes || "")}</textarea>
       <div class="actions">
         <button type="submit" class="btn">Save changes</button>
         <a href="/books/${encodeURIComponent(book.id)}" class="btn secondary">Cancel</a>
       </div>
     </form>`,
    req
  );
}

function notFoundView(req) {
  return page(
    "Not found",
    `<h1>Not found</h1>
     <p class="muted">That page doesn't exist.</p>
     <p><a href="/">Go home</a></p>`,
    req
  );
}

// ---------- request handler ----------
async function handle(req, res) {
  const url = new URL(req.url, `http://${req.headers.host || "localhost"}`);
  const pathname = url.pathname.replace(/\/+$/, "") || "/";
  const method = req.method;

  // static-ish routes
  if (pathname === "/" && method === "GET") {
    const books = await readBooks();
    return sendHtml(res, 200, homeView(books, req));
  }

  if (pathname === "/books/new" && method === "GET") {
    return sendHtml(res, 200, newBookView(req));
  }

  if (pathname === "/books" && method === "POST") {
    const form = await parseForm(req);
    const title = (form.title || "").trim();
    if (!title) return sendHtml(res, 422, newBookView(req, form, "Title is required."));
    const books = await readBooks();
    const book = {
      id: crypto.randomUUID(),
      title,
      author: (form.author || "").trim(),
      notes: (form.notes || "").trim(),
      status: "reading",
      addedAt: new Date().toISOString(),
      finishedAt: null,
    };
    books.push(book);
    await writeBooks(books);
    return redirect(res, `/books/${book.id}`);
  }

  // /books/:id and sub-routes
  const detail = pathname.match(/^\/books\/([^/]+)$/);
  const finish = pathname.match(/^\/books\/([^/]+)\/finish$/);
  const editGet = pathname.match(/^\/books\/([^/]+)\/edit$/);
  const editPost = pathname.match(/^\/books\/([^/]+)\/edit$/);
  const del = pathname.match(/^\/books\/([^/]+)\/delete$/);

  const idMatch = detail || finish || editGet || editPost || del;
  if (!idMatch) return sendHtml(res, 404, notFoundView(req));

  const id = decodeURIComponent(idMatch[1]);
  const books = await readBooks();
  const book = findBook(books, id);
  if (!book) return sendHtml(res, 404, notFoundView(req));

  if (detail && method === "GET") {
    return sendHtml(res, 200, bookView(book, req));
  }

  if (finish && method === "POST") {
    if (book.status !== "finished") {
      book.status = "finished";
      book.finishedAt = new Date().toISOString();
      await writeBooks(books);
    }
    return redirect(res, `/books/${book.id}`);
  }

  if (editGet && method === "GET") {
    return sendHtml(res, 200, editBookView(book, req));
  }

  if (editPost && method === "POST") {
    const form = await parseForm(req);
    const title = (form.title || "").trim();
    if (!title) return sendHtml(res, 422, editBookView(book, req, "Title is required."));
    book.title = title;
    book.author = (form.author || "").trim();
    book.notes = (form.notes || "").trim();
    await writeBooks(books);
    return redirect(res, `/books/${book.id}`);
  }

  if (del && method === "POST") {
    const idx = books.findIndex((b) => b.id === book.id);
    if (idx !== -1) books.splice(idx, 1);
    await writeBooks(books);
    return redirect(res, "/");
  }

  return sendHtml(res, 405, page("Method not allowed", `<h1>Method not allowed</h1>`, req));
}

const server = http.createServer((req, res) => {
  handle(req, res).catch((err) => {
    console.error("Unhandled error:", err);
    if (!res.headersSent) {
      sendHtml(res, 500, page("Server error", `<h1>Something went wrong</h1>`, req));
    }
  });
});

server.listen(PORT, () => {
  console.log(`Booklog running at http://localhost:${PORT}`);
});

